#!/usr/bin/env node
/**
 * Draw the feature art for the 13 training categories.
 *
 *   npm run art:categories       -> web/img/cards/cat/<slug>.webp
 *
 * These are DRAWN, not generated by a model. That is the point: the basket is
 * one shared path traced from web/img/logo-mark.png, so every basket in the set
 * is the logo's basket by construction and cannot drift from it, and nothing
 * here can quietly grow a hand holding a disc.
 *
 * Geometry came from reading the logo's pixels rather than eyeballing it
 * (256x256 source): the top band spans x 54-212 over y 13-40, four chain bars
 * splay from centres 75.5/114.5/152/191 at the top to 84/117.5/149.5/182.5 at
 * the bottom, the tray is a trapezoid 51-215 narrowing to 58-208 over
 * y 157-185, and the post runs y 185-241 tapering 126-141 to 129-138.
 *
 * ── What changed, and why ──────────────────────────────────────────────────
 * The first version gave almost every card the same four things: cream ground,
 * green hill, orange sun, charcoal basket, orange arc. Six of the thirteen were
 * effectively one drawing -- driving, forehand, form-technique and approach
 * were distinguishable only by how far the arc bent -- so a page of them read
 * as one card repeated, and none of them said anything about its category.
 *
 * Two rules now:
 *
 *   1. ONE IDEA PER CARD. A card carries a single subject. No sun AND hill AND
 *      trees AND arc AND basket stacked into one 880x495 frame at the size a
 *      phone actually shows it (a 126px-tall strip).
 *   2. ITS OWN COLOUR. Each category owns a ground colour, so thirteen cards in
 *      a list are thirteen different things at a glance, before any shape is
 *      read. The hues are mid-to-deep because .artcard lays a left-to-right
 *      scrim (0.93 alpha at the left edge, 0.12 at the right), which means the
 *      colour only really shows in the right ~40% and the white title always
 *      sits on near-black regardless of which card it is.
 *
 * The basket is now used only where a basket IS the subject. Drawing it on all
 * thirteen was most of what made them look alike.
 *
 * Composition is unchanged: the subject sits on the RIGHT and the left is kept
 * clear, because that is where .artcard puts the title.
 */
const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

const OUT = path.join(__dirname, '..', 'web', 'img', 'cards', 'cat');
const W = 880, H = 495;

// web/styles/tokens.css
const ORANGE = '#fc6414';
const PEACH = '#f7f4ef';   // the logo's basket white — the subject colour

/**
 * The logo's basket. `s` scales the 256-unit source; (x, y) is its top-left.
 * Drawn from the measurements above, so it is the same object every time.
 */
function basket(x, y, s, fill = PEACH) {
  const u = (n) => n * s;
  const bars = [[75.5, 84], [114.5, 117.5], [152, 149.5], [191, 182.5]];
  const bw = 8;
  return [
    `<rect x="${x + u(54)}" y="${y + u(13)}" width="${u(158)}" height="${u(27)}"
       rx="${u(13)}" fill="${fill}"/>`,
    ...bars.map(([t, b]) =>
      `<path d="M${x + u(t - bw / 2)} ${y + u(40)} L${x + u(t + bw / 2)} ${y + u(40)}
                L${x + u(b + bw / 2)} ${y + u(157)} L${x + u(b - bw / 2)} ${y + u(157)} Z"
         fill="${fill}"/>`),
    `<path d="M${x + u(51)} ${y + u(157)} L${x + u(215)} ${y + u(157)}
              L${x + u(208)} ${y + u(185)} L${x + u(58)} ${y + u(185)} Z" fill="${fill}"/>`,
    `<path d="M${x + u(126)} ${y + u(185)} L${x + u(141)} ${y + u(185)}
              L${x + u(138)} ${y + u(241)} L${x + u(129)} ${y + u(241)} Z" fill="${fill}"/>`,
  ].join('');
}

/** A disc, always flat — on the ground, in flight, or as a mark. Never held. */
const disc = (cx, cy, rx, fill = PEACH, ry = rx * 0.34) =>
  `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}"/>`;

const pine = (x, base, h, fill) => {
  const w = h * 0.46;
  return `<path d="M${x} ${base - h} L${x + w / 2} ${base} L${x - w / 2} ${base} Z" fill="${fill}"/>`
    + `<rect x="${x - h * 0.03}" y="${base}" width="${h * 0.06}" height="${h * 0.08}" fill="${fill}"/>`;
};

/** An open stroked path — the one mark most of these cards are built from. */
const stroke = (d, color, wdt = 14, dash = '') =>
  `<path d="${d}" fill="none" stroke="${color}" stroke-width="${wdt}"
     stroke-linecap="round" stroke-linejoin="round"${dash ? ` stroke-dasharray="${dash}"` : ''}/>`;

const ring = (cx, cy, r, color, wdt = 12) =>
  `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${wdt}"/>`;

/** Ground tint for a secondary mark: the peach, dropped back. */
const SOFT = 'rgba(247,244,239,0.30)';
const SOFTER = 'rgba(247,244,239,0.16)';

// ── the thirteen ────────────────────────────────────────────────────────────
// ground: the category's own colour. scene: one subject, on the right.
const CARDS = {
  'getting-started': {
    ground: '#2e7d57',                       // brand fairway green
    // The basket alone, big. This is the one card where "a disc golf basket"
    // is exactly the subject, so it gets it and the others do not.
    scene: () => basket(560, 96, 1.18),
  },

  'form-technique': {
    ground: '#34477e',
    // The S a backhand actually flies: out, over, back. No basket — the shape
    // of the flight IS the lesson.
    scene: () => stroke('M420 418 C 520 418 548 250 640 250 C 736 250 742 384 826 350', PEACH, 17)
      + disc(826, 350, 30, ORANGE),
  },

  putting: {
    ground: '#0f6f6c',
    // Circle 1: the basket inside the ring you putt from.
    scene: () => ring(660, 250, 190, SOFT, 14) + ring(660, 250, 120, SOFTER, 12)
      + basket(566, 118, 0.98),
  },

  driving: {
    ground: '#c0500f',
    // One long, low, flat arc running the full width — distance, nothing else.
    scene: () => `<rect x="396" y="398" width="104" height="20" rx="8" fill="rgba(0,0,0,0.30)"/>`
      + stroke('M430 396 Q 660 168 880 222', PEACH, 17),
  },

  approach: {
    ground: '#a06a17',
    // Short and steep, dropping in. The basket is small because the shot is
    // already close; the arc is the subject.
    scene: () => stroke('M452 424 Q 560 232 664 330', PEACH, 16)
      + basket(636, 150, 0.86) + disc(664, 336, 26, 'rgba(0,0,0,0.38)'),
  },

  forehand: {
    ground: '#6b3a78',
    // The mirror of form-technique, bending the other way — which is the whole
    // difference between the two shots.
    scene: () => stroke('M420 250 C 520 250 548 418 640 418 C 736 418 742 284 826 318', PEACH, 17)
      + disc(826, 318, 30, ORANGE),
  },

  'disc-selection': {
    ground: '#2b5f80',
    // Three discs, flat, fanned. A bag is a choice between discs, so the card
    // is the choice and nothing else.
    scene: () => disc(520, 330, 92, 'rgba(0,0,0,0.18)', 30) + disc(520, 312, 92, PEACH, 30)
      + disc(660, 356, 80, 'rgba(0,0,0,0.18)', 26) + disc(660, 340, 80, ORANGE, 26)
      + disc(778, 382, 68, 'rgba(0,0,0,0.18)', 23) + disc(778, 368, 68, '#9fc7d8', 23),
  },

  'course-strategy': {
    ground: '#4a6b2f',
    // A route picked between obstacles — the dashed line is the plan.
    scene: () => pine(508, 406, 128, '#20361a') + pine(846, 386, 104, '#20361a')
      + stroke('M420 438 Q 556 344 664 372 Q 788 400 796 236', PEACH, 14, '2 32'),
  },

  'mental-game': {
    ground: '#243358',
    // Focus: rings closing on a centre, with nothing else in the frame to look
    // at. The one card that is deliberately empty.
    scene: () => ring(662, 248, 208, SOFTER, 14) + ring(662, 248, 148, SOFT, 14)
      + ring(662, 248, 88, PEACH, 14) + disc(662, 248, 26, ORANGE, 26),
  },

  'fitness-warmup': {
    ground: '#9e3040',
    // A pulse. It reads as "body" instantly and needs no figure, which keeps
    // the no-people rule without having to draw around it.
    scene: () => stroke('M400 300 L500 300 L546 210 L606 386 L662 262 L706 300 L830 300', PEACH, 16),
  },

  'tournament-competition': {
    ground: '#8a6a1f',
    // A podium. Three blocks, one disc on the top step.
    scene: () => `<rect x="612" y="238" width="136" height="168" rx="6" fill="${PEACH}"/>`
      + `<rect x="474" y="300" width="128" height="106" rx="6" fill="rgba(247,244,239,0.62)"/>`
      + `<rect x="758" y="326" width="128" height="80" rx="6" fill="rgba(247,244,239,0.42)"/>`
      + disc(680, 220, 44, ORANGE),
  },

  'rules-etiquette': {
    ground: '#3a4652',
    // The rule sheet. An earlier version drew a marker flag with a disc lying
    // beside it, which at card size read as a golf flagstick and a golf ball on
    // a green -- ball golf, on a disc golf app that has already had to purge
    // ball-golf videos out of this very library. A page of rules cannot be
    // mistaken for another sport.
    scene: () => `<rect x="560" y="126" width="252" height="266" rx="14" fill="${PEACH}"/>`
      + `<rect x="596" y="172" width="118" height="17" rx="8" fill="${ORANGE}"/>`
      + [0, 1, 2, 3].map((i) =>
          `<rect x="596" y="${224 + i * 38}" width="${i === 3 ? 108 : 180}" height="13" rx="6"
             fill="rgba(58,70,82,0.38)"/>`).join(''),
  },

  practice: {
    ground: '#9c4a2a',
    // The same throw, again. Four identical discs in a line, evenly spaced —
    // repetition drawn literally.
    scene: () => [0, 1, 2, 3].map((i) =>
      disc(466 + i * 124, 286, 62, i === 3 ? ORANGE : PEACH)).join(''),
  },
};

const svg = (ground, body) => `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"
  viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="${ground}"/>${body}</svg>`;

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const slugs = Object.keys(CARDS);

  // Two cards sharing a ground colour would undo the point of the exercise.
  const seen = new Map();
  for (const s of slugs) {
    const g = CARDS[s].ground;
    if (seen.has(g)) throw new Error(`${s} and ${seen.get(g)} share the ground colour ${g}`);
    seen.set(g, s);
  }

  for (const slug of slugs) {
    const { ground, scene } = CARDS[slug];
    const file = path.join(OUT, slug + '.webp');
    await sharp(Buffer.from(svg(ground, scene()))).resize(W, H).webp({ quality: 88 }).toFile(file);
    const kb = Math.round(fs.statSync(file).size / 1024);
    console.log('  ' + slug.padEnd(24) + ground + '  ' + W + 'x' + H + '  ' + kb + ' KB');
  }
  const total = slugs.reduce((n, s) => n + fs.statSync(path.join(OUT, s + '.webp')).size, 0);
  console.log(`\n${slugs.length} cards, ${slugs.length} distinct grounds, ` +
    `${Math.round(total / 1024)} KB total -> ${path.relative(process.cwd(), OUT)}`);
})();
